/**  Someone in a project, with their role there. */
export type Member = {
	user: User,
	role: Role,
};

export type Node = {
	id: string,
	kind: NodeKind,
	/**  Top-left corner in world coordinates */
	x: number,
	y: number,
	w: number,
	h: number,
	text: string,
	color: NodeColor,
	/**  A color of one's own (`#rrggbb`, from the color wheel): used instead of `color` */
	tint?: string | null,
	/**
	 *  The frame (section, swimlane, package, ...) this node belongs to: it moves
	 *  along with that frame. Set when the node is added or dropped inside one.
	 */
	parent?: string | null,
	/**  Only for `Lanes`, left to right. `w` is always the sum of their sizes. */
	lanes?: Lane[] | null,
	/**  Cannot be moved, resized or deleted until unlocked (it can still be selected by clicking it) */
	locked?: boolean | null,
	/**  Only for `Image`: the id of its file on the server */
	image?: string | null,
	/**
	 *  Only for `Icon`: its shapes, in a 24×24 box, as the icon set has them:
	 *  the element (`path`, `circle`, ...) and its attributes
	 */
	icon?: ([string, { [key in string]: string }])[] | null,
	/**
	 *  Only for `Chart`: the chart board it shows (a document id) and its drawing
	 *  as last seen (refreshed when the board opens), so exports need nothing else
	 */
	chart?: ChartBlock | null,
	/**  Only for `Lifeline`: a person (UML actor), drawn as a stick figure instead of a box */
	person?: boolean | null,
	/**
	 *  The block the diagram is about: drawn heavier, in the project's accent color.
	 *  One or two per board at most, or nothing stands out.
	 */
	focal?: boolean | null,
};

export type NodeColor = "white" | "yellow" | "green" | "blue" | "purple" | "pink" | "red" | "orange" | "teal" | "gray";

export type NodeKind = "box" | "diamond" | "note" | "pill" | 
/**  Free text without a box */
"label" | 
/**  Start point: a filled circle */
"start" | 
/**  End point: a ringed circle */
"end" | 
/**  Frame with a title (in `text`) around other nodes */
"section" | 
/**  Swimlane pool with a title (in `text`) and vertical `lanes` (columns) */
"lanes" | 
/**  Fork / join: a thick bar */
"bar" | 
/**  Flow final: a circle with a cross */
"flowfinal" | 
/**  Object node: a rectangle with square corners */
"object" | 
/**  Input or output pin: a small square on the border of an action */
"pin" | 
/**  Send signal: a rectangle with an arrow point on the right */
"sendsignal" | 
/**  Accept event: a rectangle with a notch on the left */
"receivesignal" | 
/**  Time event: an hourglass with the name below */
"timeevent" | 
/**  Connector or history state ("H", "H*"): a small circle with text */
"circle" | 
/**  UML note: a rectangle with a folded corner */
"comment" | 
/**  Stick figure with the name below */
"actor" | 
/**  Ellipse */
"usecase" | 
/**  System boundary: a frame with the system name at the top */
"boundary" | 
/**
 *  Class with compartments. In `text`, a line with only `--` starts the next
 *  compartment: name, then attributes, then operations.
 */
"class" | 
/**  Package: a frame with its name in a tab */
"package" | 
/**  Lifeline: a head with the name and a dashed line below it */
"lifeline" | 
/**  Activation bar on a lifeline */
"activation" | 
/**  Combined fragment (alt, loop, opt, ...): a frame with the operator in a corner tag */
"fragment" | 
/**  Destruction of a lifeline: a cross */
"destroy" | 
/**  A picture uploaded to the board (`image` is its file, `text` its name) */
"image" | 
/**  A line drawing from the icon set (`icon` has its shapes) */
"icon" | 
/**  A chart board shown on this board (`chart`: which, and its drawing) */
"chart" | 
/**  A mind map topic: joined to its subtopics, laid out as a tree to the right */
"topic" | 
/**  An editorial note beside the diagram: text with an accent bar, joined by a thin line to what it is about */
"callout";

/**  One notice in someone's inbox. */
export type Notification = {
	id: string,
	kind: NotificationKind,
	projectId: string | null,
	projectName: string | null,
	documentId: string | null,
	documentName: string | null,
	/**  The comment it is about (for mentions and replies), to show its thread */
	commentId: string | null,
	/**  Who did it */
	actor: string,
	/**  The start of the comment */
	excerpt: string,
	createdAt: number,
	readAt: number | null,
};

export type NotificationKind = 
/**  Someone @mentioned you in a comment */
"mention" | 
/**  Someone answered in a thread you wrote in */
"reply";

/**  A point on the canvas, in world coordinates. */
export type Point = {
	x: number,
	y: number,
};

/**
 *  Where Arrange puts a node: its new top-left corner, and for a section or
 *  swimlane its new size (fitted around what is in it).
 */
export type Position = {
	id: string,
	x: number,
	y: number,
	w?: number | null,
	h?: number | null,
	/**  A swimlane's lane widths, left to right */
	lanes?: number[] | null,
};

export type Priority = "urgent" | "high" | "medium" | "low";

/**
 *  A project, stored as `projects/<id>/project.json`.
 * 
 *  Folders live inside the project file rather than as real directories on
 *  disk, so moving or renaming a folder only touches this one file.
 */
export type Project = {
	id: string,
	name: string,
	/**  Project description in markdown */
	description: string,
	folders: Folder[],
	/**  Position in the sidebar */
	order: number,
	updatedAt?: number | null,
	/**  What the logged-in user may do in this project (from the server; None in the desktop app's own files) */
	role?: Role | null,
	/**  The project's look, for all its boards and their exports */
	brand?: Brand | null,
};

/**  A board someone opened lately (newest first). */
export type RecentBoard = {
	documentId: string,
	projectId: string,
	name: string,
	kind: DocumentKind,
	diagram?: DiagramType | null,
	/**  Milliseconds since 1970 */
	openedAt: number,
};

/**  What happens to the foreign key when the referenced row is deleted or updated. */
export type RefAction = "noAction" | "restrict" | "cascade" | "setNull" | "setDefault";

/**
 *  A relation between two tables: `from` holds the foreign key to `to`,
 *  e.g. Order (many) ── Customer (one).
 */
export type Relation = {
	id: string,
	/**  The table with the foreign key */
	from: string,
	/**  The referenced table */
	to: string,
	/**  How many `from` rows belong to one `to` row (drawn at the `from` end) */
	fromCardinality: Cardinality,
	/**  How many `to` rows belong to one `from` row (drawn at the `to` end) */
	toCardinality: Cardinality,
	label?: string | null,
	/**
	 *  The join: foreign key columns in `from` and the columns they reference in `to`.
	 *  Not used when both sides are many: that becomes a junction table.
	 */
	columns?: ColumnPair[],
	onDelete?: RefAction,
	onUpdate?: RefAction,
};

/**
 *  What someone may do with a project or a board. Each role can do everything
 *  the ones before it can (`Role::Editor >= Role::Commenter`).
 */
export type Role = 
/**  Not even visible (a board hidden from a project member) */
"none" | "viewer" | 
/**  View, and add comments */
"commenter" | "editor" | 
/**
 *  Everything the owner can do (also inviting and removing people), except
 *  deleting the project or changing the owner
 */
"coOwner" | 
/**  Edit, and decide who has access */
"owner";

/**  A board whose content matches a search (Cmd+K), with the matching text. */
export type SearchHit = {
	documentId: string,
	projectId: string,
	name: string,
	kind: DocumentKind,
	diagram?: DiagramType | null,
	/**  The matching text (a block, a card, a table), shortened around the match */
	snippet: string,
};

/**  A board's public link. */
export type ShareLink = {
	token: string,
	access: LinkAccess,
};

/**  What a share link opens. */
export type SharedBoard = {
	documentId: string,
	projectId: string,
	name: string,
	/**  What the person who opened the link may do */
	role: Role,
};

/**  A sprint: a few weeks of work, with the cards picked for it (`KanbanCard::sprint_id`). */
export type Sprint = {
	id: string,
	name: string,
	/**  What the sprint is for */
	goal?: string,
	/**  `YYYY-MM-DD` */
	startDate?: string | null,
	/**  `YYYY-MM-DD` */
	endDate?: string | null,
	state?: SprintState,
	/**  The day it was completed, `YYYY-MM-DD` */
	completedOn?: string | null,
	/**  How many cards were not done when it was completed (they moved on) */
	carriedOver?: number | null,
};

export type SprintState = 
/**  Planned, not started */
"planned" | "active" | 
/**  Completed: its cards no longer show on the board */
"done";

/**  The databases SQL can be generated for. */
export type SqlDialect = "postgres" | "mysql" | "sqlite" | "sqlserver" | "oracle";

/**
 *  What `import_sql` read from SQL: new tables (already laid out from (0, 0)),
 *  the relations between them, and notes on what it could not use.
 */
export type SqlImport = {
	entities: Entity[],
	relations: Relation[],
	/**  Groups of tables (DBML's `TableGroup`), already around their tables */
	sections?: EerSection[],
	skipped: string[],
};

/**  A project or board someone starred. */
export type Star = {
	itemId: string,
	kind: ItemKind,
};

/**  An index on one or more columns of a table. */
export type TableIndex = {
	id: string,
	/**  Made from the table and columns when empty: `idx_orders_customer_id` */
	name?: string,
	/**  Attribute ids, in index order */
	columns: string[],
	unique?: boolean,
};

export type Template = {
	meta: TemplateMeta,
	content: DocContent,
};

/**  A board someone saved to start new boards from, without its content. */
export type TemplateMeta = {
	id: string,
	name: string,
	kind: DocumentKind,
	createdAt: number,
};

export type TextDoc = {
	markdown: string,
};

/**  A deleted board or project, which can be restored for 30 days. */
export type TrashItem = {
	id: string,
	kind: ItemKind,
	name: string,
	/**  A board's project (its id and name) */
	projectId?: string | null,
	projectName?: string | null,
	/**  A board's kind and type, for its icon */
	docKind?: DocumentKind | null,
	diagram?: DiagramType | null,
	/**  Milliseconds since 1970 */
	deletedAt: number,
};

export type User = {
	id: string,
	email: string,
	name: string,
	avatarUrl: string | null,
};

/**  A saved state of a board, with its content. */
export type Version = {
	meta: VersionMeta,
	content: DocContent,
};

/**  A saved state of a board, without its content (the history list). */
export type VersionMeta = {
	id: string,
	/**  Given when saved by hand; none for the ones kept automatically */
	name?: string | null,
	/**  The name of who saved it (or whose change was kept) */
	createdBy?: string | null,
	/**  Milliseconds since 1970 */
	createdAt: number,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

